Next, we will prepare the data by calculating daily returns for both the stock and the market index. tq_transmute() is used to manipulate stock data by creating a new variable, stock_return. Stock (or market) returns are calculated as the difference between the current and the past return divided by the past return. Because we are looking at daily data, the past return refers to the return that occurred on the previous trading day. na.omit() is used to drop observations with missing values.

# Calculate daily returns for the stock and the market
stock_returns &lt;- stock_data |&gt; 
  tq_transmute(select = adjusted, 
               mutate_fun = periodReturn, 
               period = "daily", 
               col_rename = "stock_return")

market_returns &lt;- market_data |&gt; 
  tq_transmute(select = adjusted, 
               mutate_fun = periodReturn, 
               period = "daily", 
               col_rename = "market_return")

# Combine the returns data into one data frame
returns_data &lt;- left_join(stock_returns, market_returns, 
                          by = "date") |&gt; 
  na.omit()
# Print the returns data
datatable(returns_data) |&gt; 
  formatRound(columns = c("stock_return","market_return"), digits = 4)







We will visualize the stock prices of Apple using ggplot2 with a nice theme.

# Plot the stock prices using highcharter
highchart() |&gt; 
  hc_title(text = "NVIDIA Inc. (NVDA) Stock Prices") |&gt;
  hc_xAxis(type = "datetime", title = list(text = "Date")) |&gt;
  hc_yAxis(title = list(text = "Adjusted Closing Price")) |&gt;
  hc_add_series(stock_data, type = "line",
                hcaes(x = date, y = adjusted),
                name = "Adjusted Price") |&gt;
  hc_tooltip(pointFormat = "Price: &lt;b&gt;${point.y:.2f}&lt;/b&gt;") |&gt;
  hc_title(style = list(fontSize = "16px", align = "center")) |&gt; 
  hc_add_theme(hc_theme_smpl())




# Step 1: Fit the linear model
fit &lt;- lm(stock_return ~ market_return, data = returns_data)

# Step 2: Add fitted values to the data
returns_data$fit &lt;- predict(fit)

# Step 3: Scatterplot of Stock Return vs. Market Return
highchart() |&gt;
  hc_title(text = "Linear Relation: NVIDIA vs. S&P 500") |&gt;
  hc_xAxis(title = list(text = "Market Return (^GSPC)")) |&gt;
  hc_yAxis(title = list(text = "Stock Return (NVDA)")) |&gt;
  hc_add_series(
    data = returns_data,
    type = "scatter",
    hcaes(x = market_return, y = stock_return),
    name = "Daily Returns",
  ) |&gt;
  hc_add_series(
    data = returns_data[order(returns_data$market_return), ],  # sort to connect line smoothly
    type = "line",
    hcaes(x = market_return, y = fit),
    name = "Linear Fit",
  ) |&gt;
  hc_tooltip(pointFormat = "Market Return: {point.x:.4f}&lt;br&gt;Stock Return: {point.y:.4f}") |&gt;
  hc_legend(align = "center", verticalAlign = "bottom") |&gt; 
  hc_add_theme(hc_theme_smpl())
